const http = require("http");
const path = require("path");

const root = path.resolve(process.argv[2] || process.cwd());
const port = 4173;
const host = "127.0.0.1";
const types = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "text/javascript",
  ".json": "application/json",
